#!/usr/bin/env sh
# Regenerates Sources/BouncerCLI/GeneratedVersion.swift with the current tag and commit SHA.
# Run this as part of cutting a release, before tagging, then commit the result.
set -eu

VERSION="${1:?usage: generate-version.sh <version, e.g. 0.1.0>}"
SHA="$(git rev-parse HEAD)"
OUT="$(dirname "$0")/../Sources/BouncerCLI/GeneratedVersion.swift"

cat > "$OUT" <<SWIFT
/// The installed build's version and origin commit, baked in at release time.
///
/// Generated by Scripts/generate-version.sh. Do not edit by hand.
enum GeneratedVersion {
    static let versionString = "${VERSION}"
    static let commitSHA = "${SHA}"
}
SWIFT

echo "Wrote ${OUT} (version ${VERSION}, commit ${SHA})"
